def model_summary() -> Dict[str, Any]:
    seido = json.loads(SEIDO_FILE.read_text(encoding="utf-8"))
    spec = model_spec()
    spec = {k: v for k, v in spec.items() if k != "説明"}
    return zaimu.build(zaimu.parse_spec(spec), youken.read_requirements(seido)).summary


def thousand(v: float) -> str:
    """円 → 「12,345千円」（千円未満は切り捨て）。"""
    return f"{int(v // 1000):,}千円"


def thousand_round(v: float) -> str:
    """円 → 「12,345千円」（千円未満は四捨五入。年ごとの数値計画の表に書く数。kakunin の照らしは表の桁の半分まで）。"""
    return f"{int((Decimal(repr(float(v))) / 1000).quantize(Decimal(1), rounding='ROUND_HALF_UP')):,}千円"


def model_values() -> Dict[str, str]:
    """計画書の本文に書く、財務モデルからの数字（文字のまま）。"""
    s = model_summary()
    ind, total = s["指標"], s["合算"]
    out = {
        "単価_パック": f"{SALES_PER_PACK}円",
        "増えるパック_満年度": "200,000パック",
        "労働生産性_基準年度": thousand(ind["労働生産性"][0]),
        "労働生産性_5年目": thousand(ind["労働生産性"][5]),
        "労働生産性の伸び_5年目": f"{ind['労働生産性の伸び'][5]:.2f}%",
        "1人当たり給与の伸び_5年目": f"{ind['1人当たり給与の伸び'][5]:.2f}%",
        "1人当たり給与支給総額_基準年度": thousand(ind["1人当たり給与"][0]),
        "1人当たり給与支給総額_5年目": thousand(ind["1人当たり給与"][5]),
        "付加価値額_基準年度": thousand(ind["付加価値額"][0]),
        "売上_5年目": thousand(total["売上"][5]),
        "営業利益_5年目": thousand(total["営業利益"][5]),
        "付加価値額_5年目": thousand(ind["付加価値額"][5]),
    }
    # 4. 財務計画の、年ごとの数値計画の表（1〜4年目。5年目は上の値）
    for year in range(1, 5):
        out[f"売上_{year}年目"] = thousand_round(total["売上"][year])
        out[f"営業利益_{year}年目"] = thousand_round(total["営業利益"][year])
        out[f"付加価値額_{year}年目"] = thousand_round(ind["付加価値額"][year])
        out[f"給与支給総額_{year}年目"] = thousand_round(total["給与支給総額"][year])
    out["給与支給総額_5年目"] = thousand_round(total["給与支給総額"][5])
    return out


def model_numbers() -> Dict[str, float]:
    """本文の計算の行（増える付加価値額と、給与に回す額など）に使う、財務モデルの数（円）。"""
