    return {"付加価値額_基準年度": s["指標"]["付加価値額"][0], "付加価値額_5年目": s["指標"]["付加価値額"][5],
            "給与支給総額_基準年度": s["合算"]["給与支給総額"][0], "給与支給総額_5年目": s["合算"]["給与支給総額"][5],
            "営業利益_基準年度": s["合算"]["営業利益"][0], "営業利益_5年目": s["合算"]["営業利益"][5]}


