def R(text: str, kind: str, source: str, *probes: str) -> Dict[str, Any]:
    """根拠対照表の1行の元。source は「回答表:E-01」「書類:<ファイル>」「モデル:<名前>」「計算:<説明>」「社長」。
    probes は、出典の中にあるはずの語（省けば、記述から「約」を除いたもの）。"""
    return {"記述": text, "種類": kind, "出典の元": source, "照らす語": list(probes) or [text.lstrip("約")]}


def model_rows(m: Dict[str, str], names: Sequence[str]) -> List[Dict[str, Any]]:
    """年ごとの数値計画の表（1〜5年目）の、財務モデルを出典にした行。同じ数（3〜5年目の売上など）は1行にまとめ、
    出典は後の年（5年目）にする（前の計画書と同じく、5年目の売上・付加価値額の行が財務モデルの5年目を指す）。"""
    rows, seen = [], set()
    for name in names:
        for year in range(5, 0, -1):
            key = f"{name}_{year}年目"
            if m[key] in seen:
                continue
            seen.add(m[key])
            rows.append(R(m[key], "数字", f"モデル:{key}"))
    return rows


