def item_text(item: Dict[str, Any]) -> str:
    return "\n".join(item["段落"])


def source_text(source: str) -> str:
    """根拠対照表の「出典」の欄に書く文字。"""
    kind, _, rest = source.partition(":")
    if kind == "回答表":
        return f"社長の答え（{ANSWERED}）：{ANSWERS[rest][0]}（回答表 {rest}）"
    if kind == "書類":
        return rest
    if kind == "モデル":
        return f"財務モデル.xlsx（{rest}）"
    if kind == "計算":
        return f"計算：{rest}"
    if kind == "社長":
        return f"社長の答え（{ANSWERED}）"
    raise ValueError(f"知らない出典の元：{source}")


def evidence_rows(items: Sequence[Dict[str, Any]]) -> List[Dict[str, str]]:
    rows = []
    for it in items:
        for r in it["根拠"]:
            rows.append({"記述": r["記述"], "種類": r["種類"], "書いた場所": it["名前"], "出典": source_text(r["出典の元"])})
    return rows


