    rows = []
    for i, (name, model, qty, price) in enumerate(TSUBASA_ITEMS, start=1):
        row = {"番号": i, "名称": name, "型番": model, "数量": qty, "単価（税抜）": price, "金額（税抜）": qty * price,
               "見積書": QUOTE_T}
        if model == "TF-TS60":  # 差し戻し5：名称と型番を見積書と違えて入れた
            row["名称"], row["型番"] = "包装機", ""
        if model == "TF-CL10":  # 差し戻し2：税込の金額を入れた
            row["単価（税抜）"] = row["金額（税抜）"] = price * 110 // 100
