def font_path(bold: bool = False) -> str:
    names = ["ヒラギノ角ゴシック W6.ttc"] if bold else ["ヒラギノ角ゴシック W3.ttc"]
    names += ["ヒラギノ角ゴシック W4.ttc", "ヒラギノ丸ゴ ProN W4.ttc"]
    import unicodedata

    for base in ("/System/Library/Fonts",):
        if not Path(base).is_dir():
            continue
        found = {unicodedata.normalize("NFC", p.name): p for p in Path(base).iterdir()}
        for n in names:
            if n in found:
                return str(found[n])
    for p in ("/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",):
        if Path(p).exists():
            return p
    raise FileNotFoundError("日本語の書体が見つかりません（画面の写真を描けません）")


def screen_photo(entry: Dict[str, Any]) -> bytes:
    """差し戻しを見せる申請の画面を、スマホで撮った写真のように描く（架空の画面。実際の画面の見た目は写していない）。"""
    import io

    from PIL import Image, ImageDraw, ImageFilter, ImageFont

    W, H = 1400, 1000
    img = Image.new("RGB", (W, H), (236, 238, 241))
    d = ImageDraw.Draw(img)
    f = lambda s, b=False: ImageFont.truetype(font_path(b), s)  # noqa: E731
    d.rectangle([60, 50, W - 60, H - 50], fill=(255, 255, 255), outline=(170, 175, 182), width=2)
    d.rectangle([60, 50, W - 60, 120], fill=(70, 90, 120))
    d.text((90, 68), "申請の画面（架空の表示。テスト用）", fill=(255, 255, 255), font=f(30, True))
    d.rectangle([60, 120, W - 60, 162], fill=(255, 236, 160))
    d.text((90, 126), f"{MARK}（hojokin-oss）　実際の申請の画面ではありません", fill=(90, 70, 0), font=f(24, True))
    y = 195
    rows = [("申請番号", APPLICATION_NO), ("申請の種類", "交付申請"), ("状態", "差し戻し"),
            ("差し戻した日", f"{SENT_BACK.year}年{SENT_BACK.month}月{SENT_BACK.day}日"),
            ("直して出す期限", f"{FIX_BY.year}年{FIX_BY.month}月{FIX_BY.day}日")]
    for k, v in rows:
        d.rectangle([110, y, 420, y + 58], fill=(244, 246, 249), outline=(200, 204, 210))
        d.rectangle([420, y, W - 110, y + 58], fill=(255, 255, 255), outline=(200, 204, 210))
        d.text((130, y + 14), k, fill=(40, 40, 40), font=f(26, True))
        d.text((440, y + 14), v, fill=(200, 30, 30) if k == "状態" else (20, 20, 20), font=f(26))
        y += 58
    y += 30
    d.text((110, y), f"差し戻しの理由（修正{entry['番号']}：{entry['件名']}）", fill=(20, 20, 20), font=f(28, True))
    y += 50
    d.rectangle([110, y, W - 110, y + 200], fill=(253, 246, 246), outline=(220, 160, 160), width=2)
    ty = y + 20
    for line in entry["本文"]:
        chunk = 40
        for i in range(0, len(line), chunk):
            d.text((135, ty), line[i:i + chunk], fill=(30, 30, 30), font=f(26))
            ty += 40
    y += 230
    d.rounded_rectangle([W - 420, y, W - 110, y + 64], radius=10, fill=(70, 90, 120))
    d.text((W - 380, y + 16), "直して出し直す", fill=(255, 255, 255), font=f(26, True))
    # 撮った写真らしく：少し傾け、ぼかし、明るさのむらとざらつきを足す（同じ種から、同じ画素になる）
    photo = img.rotate(-2.2, resample=Image.BICUBIC, expand=True, fillcolor=(58, 52, 46))
    photo = photo.filter(ImageFilter.GaussianBlur(0.8))
    rnd = random.Random(20270602)
    px = photo.load()
    pw, ph = photo.size
    for yy in range(0, ph, 2):
        for xx in range(0, pw, 2):
            shade = int(18 * (xx / pw)) + rnd.randint(-6, 6)
            r, g, b = px[xx, yy]
            px[xx, yy] = (max(0, min(255, r - shade)), max(0, min(255, g - shade)), max(0, min(255, b - shade)))
    out = io.BytesIO()
    photo.save(out, format="PNG", optimize=False)
    return out.getvalue()


def requotes(out_dir: Path) -> None:
    """差し戻し1を直すために取り直した見積書2通。D2b の描き方で、見積番号・発行日・有効期限だけを替える。"""
    import make_documents_part2 as mk2

    saved = (mk2.QUOTE_DATE, mk2.QUOTE_VALID_UNTIL, copy.deepcopy(mk2.QUOTES))
    try:
        mk2.QUOTE_DATE = f"{REQUOTE_DATE.year}年{REQUOTE_DATE.month}月{REQUOTE_DATE.day}日"
        mk2.QUOTE_VALID_UNTIL = f"{REQUOTE_VALID.year}年{REQUOTE_VALID.month}月{REQUOTE_VALID.day}日"
        mk2.QUOTES["つばさ台フードシステム"]["number"] = "TFS-2706-0088"
        mk2.QUOTES["ほしみ機工"]["number"] = "HK-20270607-03"
        for key, file, doc_name in (("つばさ台フードシステム", "見積書_つばさ台フードシステム_2027年6月.pdf", "御見積書（つばさ台フードシステム、取り直し）"),
                                    ("ほしみ機工", "見積書_ほしみ機工_2027年6月.pdf", "見積書（ほしみ機工、取り直し）")):
            path = out_dir / file
            path.parent.mkdir(parents=True, exist_ok=True)
            mk2.render(path, doc_name, mk2.quote(key))
    finally:
        mk2.QUOTE_DATE, mk2.QUOTE_VALID_UNTIL, mk2.QUOTES = saved


