TARGET_PAY_GROWTH = Decimal("4.0")  # 応募のときに決めた1人当たり給与支給総額の年平均成長率の目標値（計画書 3-1）
GRANT = 15_000_000  # 交付決定額（testdata/期限 の交付決定通知書）
RAISE_OF_CAP = 0  # 補助上限の引き上げ額（大幅賃上げ特例を使っていないので0）


