def build_all(root: Path, with_words: bool = True) -> Dict[str, Any]:
    """root の下に、材料/・正解.json（と、様式があれば 作ったもの/）を作る。"""
    mat = root / MATERIAL
    if mat.exists():
        shutil.rmtree(mat)
    for key, items in plan_variants().items():
        write_json(mat / key / "本文.json", plan_json(items))
        write_text(mat / key / "本文.md", plan_markdown(PLAN_TITLES[key], items))
        write_json(mat / key / "根拠対照表.json", {"行": evidence_rows(items)})
    sb = mat / SENDBACK
    for e in SENDBACKS:
        if e["形"] == "画面の写真":
            write_bytes(sb / e["ファイル"], screen_photo(e))
        else:
            write_text(sb / e["ファイル"], sendback_text(e["番号"], e["件名"], e["本文"]))
    write_json(sb / "提出版" / "交付申請の入力.json", submitted_application())
    requotes(sb / "届いた書類")
    write_json(mat / RESULTS / "財務モデルの指定.json", model_spec())
    write_json(mat / RESULTS / "実績_1年目.json", actual_json())
    write_json(root / ANSWER_FILE, answer_json())
    made = []
    if with_words:
        made_dir = root / MADE
        if made_dir.exists():
            shutil.rmtree(made_dir)
        made = build_words(made_dir)
    return {"Word": made}


def main() -> None:
    result = build_all(HERE)
    for p in sorted((HERE / MATERIAL).rglob("*")):
        if p.is_file():
            print(f"作った：{p.relative_to(HERE).as_posix()}")
    print(f"作った：{ANSWER_FILE}")
    if result["Word"]:
        for p in result["Word"]:
            print(f"作った（Git の外）：{MADE}/{p}")
    else:
        print(f"公式の様式（{FORM.relative_to(REPO).as_posix()}）がないので、Word は作っていません")


if __name__ == "__main__":
    main()
